<?php declare(strict_types=1); require __DIR__.'/action-common.php';admin_post();try{$companyId=filter_var($_POST['empresa_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$supplierId=filter_var($_POST['fornecedor_so_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($companyId===false||$supplierId===false)throw new InvalidArgumentException('Empresa ou fornecedor inválido.');$company=$application->adminCompanies()->find($companyId);$supplier=$application->soSuppliers()->findById($supplierId);if(!$company||!$supplier)throw new InvalidArgumentException('Empresa ou fornecedor não encontrado.');if($application->adminCompanies()->integrationBySupplier($supplierId))throw new InvalidArgumentException('Fornecedor já vinculado.');$companyDocument=preg_replace('/\D/','',(string)($company['documento']??''))??'';$supplierDocument=preg_replace('/\D/','',$supplier->document)??'';if($companyDocument!==''&&$supplierDocument!==''&&$companyDocument!==$supplierDocument)throw new InvalidArgumentException('O documento da empresa é diferente do fornecedor do SO.');$application->adminCompanies()->linkSupplier($companyId,$supplierId);$session->flash('success','Fornecedor do SO vinculado com sucesso.');admin_action_redirect('adm/empresa.php?id='.$companyId);}catch(Throwable $e){admin_action_error($e,'adm/empresas-so.php');}
